        string cwd=Directory.GetCurrentDirectory();string? oldGate=Environment.GetEnvironmentVariable("PROJECT_PRIME_CUSTOM_WEAPON_PLAYBACK"),oldStore=Environment.GetEnvironmentVariable("PROJECT_PRIME_WEAPON_STORE");NativeWindow? window=null;DesktopGraphicsSession? graphics=null;
        try
