            input=Path.GetFullPath(input);output=Path.GetFullPath(output);Directory.CreateDirectory(output);string loaded=typeof(DemoPlayback).Assembly.Location;Console.WriteLine("Loaded ProjectPrime: "+loaded+" SHA256="+Convert.ToHexStringLower(SHA256.HashData(File.ReadAllBytes(loaded))));string archive=Path.Combine(input,"actual-full-custom"+DemoFile.Extension);byte[] package=File.ReadAllBytes(Path.Combine(input,"variant.ppweapon"));if(package.Length>32*1024*1024)throw new InvalidDataException("Package bound.");var parsed=WeaponPackage.Parse(package);string storeRoot=Path.Combine(output,"store");var store=new WeaponPackageStore(storeRoot);using var json=JsonDocument.Parse(File.ReadAllBytes(Path.Combine(input,"file-expected-worlds.json")));var rows=json.RootElement.EnumerateArray().Select(row=>(Name:row.GetProperty("name").GetString()!,Frame:row.GetProperty("frame").GetUInt32(),File:row.GetProperty("filename").GetString()!)).ToArray();if(rows.Length is <1 or >8)throw new InvalidDataException("Bounded genuine targets required.");uint origin=rows.Single(row=>row.Name=="baseline").Frame,end=rows.Single(row=>row.Name=="end").Frame;int checks=0;void Check(bool ok,string label){if(!ok)throw new InvalidDataException(label);checks++;}bool Join()=>Task.Run(()=>DemoPlayback.Join(archive)).GetAwaiter().GetResult();var stages=new List<object>();
            DemoPlayback.Stop();Environment.SetEnvironmentVariable("PROJECT_PRIME_CUSTOM_WEAPON_PLAYBACK",null);Environment.SetEnvironmentVariable("PROJECT_PRIME_WEAPON_STORE",storeRoot);Check(!Join()&&!DemoPlayback.IsActive&&DemoPlayback.LastResult==ReplayOpenResult.UnsupportedFormat,"default-off ordinary Join refuses custom file without native fallback");Environment.SetEnvironmentVariable("PROJECT_PRIME_CUSTOM_WEAPON_PLAYBACK","1");Check(!Join()&&!DemoPlayback.IsActive&&DemoPlayback.PresentationScene==null&&!Directory.Exists(storeRoot)&&DemoPlayback.LastError!=null,"opt-in missing exact package refuses without creating store or native Scene");DemoPlayback.Stop();
            store.Install(package);Check(Join()&&DemoPlayback.IsActive&&DemoPlayback.Session.Host.Match.HasValue&&ReplayController.CurrentFrame==0&&ReplayController.DurationFrames==end-origin&&DemoPlayback.PresentationScene==null,"worker ordinary Join exposes real match/duration at relative zero without Scene adoption");object requestOwner=DemoPlayback.RequestOwner;Check(Join()&&ReferenceEquals(requestOwner,DemoPlayback.RequestOwner),"repeated same-path worker preflight reuses exact request owner");uint requestFrame=DemoPlayback.Session.RecordingFrame;void RejectRequest(Action action,string label){try{action();throw new InvalidDataException("Request unexpectedly accepted "+label);}catch(InvalidOperationException){Check(DemoPlayback.IsActive&&DemoPlayback.Session.RecordingFrame==requestFrame&&ReferenceEquals(requestOwner,DemoPlayback.RequestOwner),"request-only "+label+" refuses without changing admitted owner/clock");}}RejectRequest(()=>DemoPlayback.Session.PumpFrame(),"native PumpFrame");RejectRequest(()=>DemoPlayback.Session.Reposition(0,0),"native Reposition");Check(store.Uninstall(parsed.PackageHash)&&store.Prune()==0,"unadopted ordinary request retains exact historical package");DemoPlayback.Stop();Check(store.Prune()==1&&!DemoPlayback.IsActive,"close-before-adoption releases retained package/reader");
