            string data=File.ReadAllText(Path.Combine(input,"replay-fixture-data.txt"));Directory.SetCurrentDirectory(data);Paths.UpdatePaths();Paths.ChooseMphPath();MapAudit.ForceEveryone=true;var settings=DesktopGlContext.Settings(background:true);settings.ClientSize=new(640,480);settings.StartVisible=true;settings.Title="Ordinary custom replay theatre admission";window=new NativeWindow(settings);graphics=new DesktopGraphicsSession(window);var shell=new Scene(new(640,480),SyntheticInput.CreateKeyboard(),SyntheticInput.CreateMouse(),_=>{},()=>{},initializeRuntime:false);var foreground=GameState.Current;var random=Rng.Current;uint rng1=Rng.Rng1,rng2=Rng.Rng2;bool spectator=SpectatorMode.IsSpectating,preferred=SpectatorMode.PreferSpectator,free=SpectatorMode.FreeCamera;bool network=NetSession.Active;
            void Update(){DemoPlayback.Update(shell);if(DemoPlayback.LastResult!=ReplayOpenResult.Success)throw new InvalidDataException("Ordinary theatre failed: "+DemoPlayback.LastError);}
