            void Compare((string Name,uint Frame,string File) row,string label){var world=DemoPlayback.ReviewedStudioWorld(true);using var expected=ReplayWorldCheckpoint.FromCustomBytes(File.ReadAllBytes(Path.Combine(input,row.File)));using var actual=ReplayWorldCheckpoint.CaptureCustom(world);var differences=expected.CanonicalGraphDifferences(actual);File.WriteAllText(Path.Combine(output,label+"-differences.json"),JsonSerializer.Serialize(differences));Check(differences.Length==0&&world.Session.RecordingFrame==row.Frame&&ReplayController.CurrentFrame==row.Frame-origin,"ordinary facade exact graph/clock parity "+label);}
            store.Install(package);Check(Join(),"ordinary worker prepares actual custom file for theatre");ReplayController.Pause();Settle();Check(DemoPlayback.IsCustomPlayback&&DemoPlayback.PresentationScene!=null&&DemoPlayback.ReviewedStudioWorld().Scene==DemoPlayback.PresentationScene,"ordinary Scene-thread Update adopts real bounded custom player");Check(store.Uninstall(parsed.PackageHash)&&store.Prune()==0,"adopted theatre player owns exact package after marker removal");
