                ReplayController.Seek(row.Frame-origin,resume:false);Settle();Compare(row,"seek-"+row.Name);
                foreach(var mode in new[]{ReplayCameraMode.FirstPerson,ReplayCameraMode.Free,ReplayCameraMode.Chase,ReplayCameraMode.Orbit,ReplayCameraMode.Overview})
                {
                    ReplayCamera.SetMode(mode);Check(DemoPlayback.WatchCustomSubject(0),"ordinary custom subject selection remains private");ReplayCamera.SetMode(mode);var world=DemoPlayback.ReviewedStudioWorld();var scene=DemoPlayback.PreparePresentation(shell);Check(ReferenceEquals(scene,world.Scene),"ordinary presentation adapter returns admitted private Scene");using var before=ReplayWorldCheckpoint.CaptureCustom(world);int main=scene!.Players.MainPlayerIndex;scene.OnDrawFrame();Check(scene.OnRenderFrame()&&GL.GetError()==OpenTK.Graphics.OpenGL.ErrorCode.NoError,"ordinary theatre camera renders "+mode);Check(ScreenCapture.SaveWindow(scene,Path.Combine(output,row.Name+"-"+mode+"-window.png")),"actual presented camera image retained");DesktopGraphicsSession.Present(window);scene.AfterRenderFrame();using var after=ReplayWorldCheckpoint.CaptureCustom(world);var differences=before.CanonicalGraphDifferences(after);File.WriteAllText(Path.Combine(output,row.Name+"-"+mode+"-draw-differences.json"),JsonSerializer.Serialize(differences));Check(differences.Length==0&&scene.Players.MainPlayerIndex==main,"ordinary camera draw preserves full canonical world and main actor");Check(!ReplayAudioOwner.MayPlay(scene)&&!SpectatorMode.IsSpectating&&typeof(DemoPlayback).GetField("_audio",BindingFlags.Static|BindingFlags.NonPublic)!.GetValue(null) is ulong audio&&audio==0,"custom ordinary playback remains silent without global spectator/audio owner");stages.Add(new{row.Name,row.Frame,mode=mode.ToString()});
                }
