            store.Install(package);Check(Join(),"ordinary theatre supports repeated worker open");ReplayController.Pause();Settle();DemoPlayback.Stop();Check(store.Uninstall(parsed.PackageHash)&&store.Prune()==1,"repeated adopted open/close releases all leases");Check(ReferenceEquals(foreground,GameState.Current)&&ReferenceEquals(random,Rng.Current)&&rng1==Rng.Rng1&&rng2==Rng.Rng2&&spectator==SpectatorMode.IsSpectating&&preferred==SpectatorMode.PreferSpectator&&free==SpectatorMode.FreeCamera&&network==NetSession.Active,"ordinary custom playback leaves foreground game RNG spectator and network owners unchanged");File.WriteAllText(Path.Combine(output,"theatre-results.json"),JsonSerializer.Serialize(new{checks,stages,scope="Ordinary DemoPlayback worker admission and Scene-thread bounded player over actual recorded archive; strict graph/draw/suffix/control/lease checks. Actual native GL pictures, no launcher UI pixel, audible playback or export qualification claim."},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"PASS {checks} ordinary custom replay theatre checks");return 0;
